import{_ as l,l as r,o as a,c as i,v as t,p as s,x as o,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"双曲贴现与现时偏差","description":"","frontmatter":{"title":"双曲贴现与现时偏差","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hyperbolic-present-bias.md","filePath":"econ/hyperbolic-present-bias.md","lastUpdated":1789023840000}'),E={name:"econ/hyperbolic-present-bias.md"};function h(b,e,_,A,m,u){const n=r("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="双曲贴现与现时偏差" tabindex="-1">双曲贴现与现时偏差 <a class="header-anchor" href="#双曲贴现与现时偏差" aria-label="Permalink to &quot;双曲贴现与现时偏差&quot;">​</a></h1><div class="epigraph"><p>从现在看，「明天相对后天」几乎一样重要；真到了明天，「今天相对明天」突然陡了——相对权重随等待的起点而变。</p><footer>—— Laibson, Golden Eggs and Hyperbolic Discounting, Quarterly Journal of Economics, 1997；对照 Phelps and Pollak, RES 1968</footer></div><p><a href="/econ/exponential-discounting">上一课</a>把几何 \\(\\beta^t\\) 钉成时间一致。本课缺口是：实验室与田间常见的是<strong>现时偏差</strong>——对立刻兑现的延迟特别不耐烦，对同样长度的远期延迟却接近指数。不重写贴现效用的可分骨架，只换权重。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指数贴现下，任意相邻两期的相对权重都是同一个 \\(\\beta\\)。Ainslie 的动物与人类延迟实验、以及后来的选择实验，显示短期贴现率高于长期。Phelps 与 Pollak（1968）用世代间的准双曲；Laibson（1997）把它写成个人自我序列：</p> \\[U_t=u(c_t)+\\beta\\sum_{k=1}^{\\infty}\\delta^k u(c_{t+k}), \\]<p>\\(\\delta\\) 是长期因子，\\(\\beta\\le 1\\) 是「现在」相对「以后所有期」的额外折扣。\\(\\beta\\lt 1\\) 时，从 \\(t\\) 看 \\(t+1\\) 对 \\(t+2\\) 的相对权重是 \\(\\delta\\)，从 \\(t+1\\) 看变成 \\(\\beta\\delta\\)——计划在边界上翻脸。缺口是把上一课的一致性拆掉，而不是重讲<a href="/econ/preference-choice">偏好</a>或 <a href="/econ/expected-utility">vNM</a>。</p><p><span class="marginnote">真双曲常用 \\(1/(1+k\\Delta)\\)。准双曲 \\(\\beta\\)–\\(\\delta\\) 是离散近似，便于动态规划。本课以准双曲为主，机制相同：现时额外折扣。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>自我是一串决策者，每期只有当期 \\(c_t\\) 在自己手里。幼稚型相信未来的自己仍按 \\(t\\) 的计划执行；老练型解子博弈完美均衡，知道下一期会再贴一次 \\(\\beta\\)。O&#39;Donoghue 与 Rabin（1999）把两者分开：幼稚推迟成本前置的任务、抢先做收益前置的任务；老练部分纠正，但现时偏差仍在。本课不估计 \\(\\beta\\)，只标明策略型。</p>',10)),(a(),s(c,null,{default:o(()=>[d(n,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXP%5B%22%E6%8C%87%E6%95%B0%3A%20%E7%9B%B8%E5%AF%B9%E6%9D%83%E9%87%8D%E6%81%92%E4%B8%BA%20delta%22%5D%20--%3E%20GAP%5B%22%E7%8E%B0%E6%97%B6%E9%A2%9D%E5%A4%96%E6%8A%98%E6%89%A3%20beta%22%5D%0A%20%20GAP%20--%3E%20QH%5B%22%E5%87%86%E5%8F%8C%E6%9B%B2%20U_t%22%5D%0A%20%20QH%20--%3E%20NAIVE%5B%22%E5%B9%BC%E7%A8%9A%3A%20%E4%BB%A5%E4%B8%BA%E6%9C%AA%E6%9D%A5%E4%BC%9A%E6%89%A7%E8%A1%8C%22%5D%0A%20%20QH%20--%3E%20SOPH%5B%22%E8%80%81%E7%BB%83%3A%20%E5%AD%90%E5%8D%9A%E5%BC%88%E5%AE%8C%E7%BE%8E%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>资产仍是完全债券或非流动性「金蛋」（Laibson）：非流动资产充当承诺，因为下一期的自己无法立刻吃掉本金。承诺装置的制度细节下一课再写。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是相对权重依赖「延迟从哪一天起算」。不是人算错了欧拉，是每期的 \\(U_t\\) 换了一套尺。消费路径因此有两种偏离：过度消费（相对长期自我），以及对流动性的需求——流动资产会被现时自我吃掉。这与<a href="/econ/consumption-euler">欧拉方程</a>的宏观用法不冲突：宏观主干仍用指数 \\(\\beta\\) 写前瞻 IS；补层指出，若家庭是准双曲，欧拉在「长期自我」与「现时自我」之间没有单一主体。</p><p>也不进入限价簿。现时偏差改的是家庭目标，不是报价协议。主干在交接处交给量化栏的是均衡 \\(p\\)；补层在这里改的是 \\(U_t\\) 的权重，两者不相吞。</p><p>与<a href="/econ/two-period-micro">两期</a>的切点对照：指数下切点沿时间滑动仍被承认；准双曲下 \\(t\\) 的切点在 \\(t+1\\) 被另一条无差异曲线取代。宏观<a href="/econ/consumption-euler">欧拉</a>若继续用单一 \\(\\beta\\)，写的是长期自我或代表主体，不是现时自我的一阶条件。本课把这个错位标出来，后课用承诺去焊。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>双曲不是对所有跨期选择的否证。指数贴现在长期利率、增长模型里仍是默认。本课不把政府通胀偏差（Kydland–Prescott）与个人现时偏差写成同一个方程：前者是政策对私人预期，后者是自我对自我。股权溢价、习惯形成已经在主干用别的 \\(m\\)；这里不重校准谜。</p><p>后课默认：说到现时偏差，指 \\(\\beta\\)–\\(\\delta\\) 或真双曲；说到承诺，默认读者知道老练自我愿意付出代价关掉未来的选择。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指数贴现的相对权重不随起点变；现时偏差让「现在」额外打折。</li><li>Laibson 准双曲把自我写成博弈；幼稚与老练策略不同。</li><li>不重推 vNM，不重写簿；只换跨期权重。</li><li>出处：Phelps and Pollak, <em>RES</em> 1968；Laibson, <em>QJE</em> 1997；O&#39;Donoghue and Rabin, <em>AER</em> 1999。</li></ul>',10))])}const P=l(E,[["render",h]]);export{f as __pageData,P as default};
